// ── envelopes ────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
const isRead = (action) => /\.read$/.test(action) || /\.(preview|list|get|queue)$/.test(action) || action === 'observation.evidence.retrieve' || action === 'decision.read' || action === 'retention.read';
const over = (s, action, objectType, objectId, purposeId, consequence) => ({ scope: 'DOMAIN', tenantId: T, domainId: D, principalId: `principal:${s.principalId}`, purposeId,
  action, objectType, objectId, sideEffect: isRead(action) ? 'none' : 'reversible', consequence: consequence ?? (isRead(action) ? 'C1' : 'C2'), trace: 'phase6-b40' });
const callOnce = async (path, o, payload, token) => {
  let r;
  try { r = await call(path, o, payload, token); } catch (e) { if (!/fetch failed/.test(String(e?.message))) throw e; note(`the transport was reset before an answer (${e?.cause?.code ?? e.message}); retried once`); r = await call(path, o, payload, token); }
  if (!r.ok && r.status === 503 && o.sideEffect === 'none' && /outlived its authorization context/.test(String(r.body?.message ?? ''))) { note(`the read ${o.action} outlived its authorization context (the server discarded it and says retry); read once more`); r = await call(path, o, payload, token); }
  return r;
};
const DM = (s, path, action, payload = {}, objectType = 'SRC', objectId = null, purpose = 'observation', consequence) => callOnce(path, over(s, action, objectType, objectId, purpose, consequence), payload, s.token);
const P = (s, path, action, payload = {}, objectType = 'GOV', objectId = null) => callOnce(path, { ...over(s, action, objectType, objectId, 'governance'), scope: 'PLATFORM', tenantId: null, domainId: null }, payload, s.token);
const BASE = `/v1/tenants/${T}/domains/${D}`;
