const CAST = [['a.hoffmann', 'domain_analyst', 'DOMAIN'], ['h.weber', 'domain_analyst', 'DOMAIN'], ['m.dvorak', 'collection_manager', 'DOMAIN'], ['f.aydin', 'data_steward', 'DOMAIN'],
  ['t.richter', 'domain_admin', 'DOMAIN'], ['w.zielinska', 'customer_sponsor', 'TENANT'], ['n.eriksen', 'forecast_owner', 'DOMAIN'], ['j.weber', 'strategy_owner', 'DOMAIN'],
  ['c.brenner', 'decision_owner', 'DOMAIN'], ['e.lindqvist', 'auditor', 'TENANT'], ['h.bergmann', 'retention_authority', 'TENANT'], ['l.haddad', 'design_system_authority', 'PLATFORM'],
  ['p.castellano', 'conformance_steward', 'PLATFORM'], ['h.achterberg', 'independent_assurance', 'PLATFORM']];
