const managers = await q(`select p.login_name from identity.principals p join identity.role_bindings b on b.principal_id = p.id where b.revoked_at is null and b.role_code = 'collection_manager' and b.scope = 'DOMAIN' and b.domain_id = $1 and p.status = 'active'`, [D]);
note(`the corridor's collection managers: ${managers.map((x) => x.login_name).join(', ')} — the ONLY one (MAP Q5: the analyst registers, the collection manager evaluates and approves — two people)`);
const haddad = await q(`select p.login_name, b.role_code from identity.principals p join identity.role_bindings b on b.principal_id = p.id where p.display_name like 'R. Haddad%' and b.revoked_at is null and b.domain_id = $1`, [D]);
